(() => {
 'use strict';
 document.documentElement.classList.add('js');
 const products=JSON.parse(document.getElementById('store-data').textContent), byId=new Map(products.map(p=>[p.id,p])), key='bigfoot-sg-request-v1';
 let cart={},toastTimer,storageAvailable=true;
 const validWeight=n=>Number.isFinite(n)&&n>=.5&&n<=100&&Number.isInteger(n*2);
 try{const saved=JSON.parse(localStorage.getItem(key)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))for(const [id,n] of Object.entries(saved))if(byId.has(id)&&validWeight(n))cart[id]=n;}catch{storageAvailable=false;}
 if(location.hash.startsWith('#cart=')){try{const incoming=JSON.parse(decodeURIComponent(location.hash.slice(6)));if(incoming&&typeof incoming==='object'&&!Array.isArray(incoming))for(const[id,n]of Object.entries(incoming))if(byId.has(id)&&validWeight(n))cart[id]=n;}catch{}}
 const menu=document.querySelector('.menu'),nav=document.getElementById('navigation');
 function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
 menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus();}});
 document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu();});
 matchMedia('(min-width:761px)').addEventListener('change',closeMenu);
 nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
 function announce(message){const el=document.getElementById('cart-status');el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.textContent='';},4500);}
 function save(){try{localStorage.setItem(key,JSON.stringify(cart));}catch{storageAvailable=false;}render();}
 function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
 function sprite(p){const s=el('span','cut-sprite');s.style.setProperty('--sprite-x',`${p.cell%3*50}%`);s.style.setProperty('--sprite-y',`${Math.floor(p.cell/3)*100}%`);s.setAttribute('aria-hidden','true');return s;}
 function show(id){const dialog=document.getElementById(id);if(dialog&&!dialog.open)dialog.showModal();}
 document.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
 document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 document.querySelectorAll('[data-open-cart]').forEach(b=>b.addEventListener('click',()=>{render();show('cart-dialog');}));
 document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>show(`product-${b.dataset.product}`)));
 document.querySelectorAll('[data-weight-step]').forEach(b=>b.addEventListener('click',()=>{const input=document.getElementById(b.dataset.input);const current=Number(input.value);input.value=Math.min(100,Math.max(.5,(Number.isFinite(current)?current:1)+Number(b.dataset.weightStep)));input.setCustomValidity('');}));
 document.querySelectorAll('[data-add-product]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.addProduct,input=document.getElementById(`weight-${id}`),n=Number(input.value);input.setCustomValidity(validWeight(n)?'':'Choose a quantity from 0.5 to 100 kg, in 0.5 kg steps.');if(!input.reportValidity())return;if((cart[id]||0)+n>100){input.setCustomValidity('Your cart can request up to 100 kg of this cut. Adjust the cart or contact the team for larger quantities.');input.reportValidity();return;}cart[id]=(cart[id]||0)+n;save();b.closest('dialog').close();announce(`${byId.get(id).name} added. ${cart[id]} kg in your request cart.`);}));
 document.querySelectorAll('input[name=weight]').forEach(i=>i.addEventListener('input',()=>i.setCustomValidity('')));
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const category=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{const visible=category==='all'||card.dataset.category===category;card.hidden=!visible;if(visible)count++;});document.querySelectorAll('[data-filter-status]').forEach(s=>s.textContent=`${count} ${count===1?'cut':'cuts'} to explore`);}));
 function renderList(container){container.replaceChildren();const entries=Object.entries(cart);if(!entries.length){const empty=el('div','empty-cart');empty.append(el('h3','','A little empty in here.'),el('p','','Choose a cut from the freezer to start your request.'));const link=el('a','text-link','Explore the freezer ↗');link.href='index.html#freezer';empty.append(link);container.append(empty);return;}
 for(const [id,weight]of entries){const p=byId.get(id),row=el('article','cart-item'),copy=el('div'),controls=el('div','weight-control');copy.append(el('h3','',p.name));const input=el('input');input.type='number';input.min='.5';input.max='100';input.step='.5';input.value=weight;input.inputMode='decimal';input.setAttribute('aria-label',`Requested ${p.name.toLowerCase()} weight in kg`);
 function change(n){if(!validWeight(n)){input.value=cart[id];announce('Choose 0.5–100 kg in 0.5 kg steps.');return;}const wasEditing=document.activeElement===input;cart[id]=n;save();if(wasEditing)container.querySelector(`[data-row="${id}"] input`)?.focus();}
 for(const [symbol,delta,label]of [['−',-.5,'Decrease'],['+',.5,'Increase']]){const b=el('button','',symbol);b.type='button';b.setAttribute('aria-label',`${label} ${p.name.toLowerCase()} weight`);b.disabled=delta<0?weight===.5:weight===100;b.addEventListener('click',()=>{change(weight+delta);const updated=container.querySelector(`[data-row="${id}"] button[aria-label="${label} ${p.name.toLowerCase()} weight"]`);if(updated&&!updated.disabled)updated.focus();else container.querySelector(`[data-row="${id}"] input`)?.focus();});controls.append(b);if(delta<0)controls.append(input);}
 controls.append(el('span','','kg'));input.addEventListener('change',()=>change(Number(input.value)));copy.append(controls);const remove=el('button','remove-item','Remove');remove.type='button';remove.setAttribute('aria-label',`Remove ${p.name.toLowerCase()} from cart`);remove.addEventListener('click',()=>{delete cart[id];save();announce(`${p.name} removed from your request.`);const target=container.querySelector('.remove-item')||container.querySelector('a');target?.focus();});row.dataset.row=id;row.append(sprite(p),copy,remove);container.append(row);}}
 function render(){document.querySelectorAll('[data-cart-count]').forEach(n=>n.textContent=Object.keys(cart).length);for(const id of ['cart-items','checkout-items']){const c=document.getElementById(id);if(c)renderList(c);}const review=document.getElementById('review-cart-link');review.setAttribute('aria-disabled',String(!Object.keys(cart).length));review.href='checkout.html'+(storageAvailable?'':'#cart='+encodeURIComponent(JSON.stringify(cart)));if(!storageAvailable){const info=document.querySelector('.cart-explainer');info.textContent='Browser storage is unavailable. Use Review your request to carry this selection to the request page. Your cart will not be saved for a later visit.';}}
 document.getElementById('review-cart-link').addEventListener('click',e=>{if(!Object.keys(cart).length){e.preventDefault();announce('Choose at least one cut before reviewing your request.');}});
 render();
 const form=document.getElementById('request-form');let draft='';
 if(form){form.addEventListener('submit',e=>{e.preventDefault();if(!Object.keys(cart).length){announce('Choose at least one cut before preparing a request.');document.querySelector('.checkout-cart a').focus();return;}for(const input of form.querySelectorAll('[required]')){input.setCustomValidity(input.value.trim()?'':'Please enter this detail.');if(!input.reportValidity())return;}const data=new FormData(form);draft=['BIGFOOT MEATS SINGAPORE — CART REQUEST','','Please confirm availability, final weight, pricing, preparation and delivery. This is a request, not a confirmed order.','','REQUESTED CUTS',...Object.entries(cart).map(([id,n])=>`• ${byId.get(id).name}: ${n} kg requested`),'','CUSTOMER DETAILS',`Name: ${data.get('name').trim()}`,`Email: ${data.get('email').trim()}`,`Phone: ${data.get('phone').trim()||'Not supplied'}`,`Delivery area / postal code: ${data.get('area').trim()}`,'','PREFERENCES',data.get('message').trim()||'None specified'].join('\n');document.getElementById('request-preview').textContent=draft;document.getElementById('request-email').href=`mailto:enquiries@bigfoot.com.sg?subject=${encodeURIComponent('Singapore meat request — '+data.get('name').trim())}&body=${encodeURIComponent(draft)}`;document.getElementById('copy-status').textContent='Nothing has been sent. Open your email app to send, or copy the request.';show('request-review');});form.querySelectorAll('[required]').forEach(i=>i.addEventListener('input',()=>i.setCustomValidity('')));document.getElementById('request-fields').disabled=false;
 document.getElementById('copy-request').addEventListener('click',async()=>{const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText(draft);status.textContent='Request copied. Paste it into an email to enquiries@bigfoot.com.sg.';}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents(document.getElementById('request-preview'));selection.removeAllRanges();selection.addRange(range);status.textContent='Select and copy the highlighted request, then email enquiries@bigfoot.com.sg.';}});}
 window.addEventListener('storage',e=>{if(e.key===key){try{const incoming=JSON.parse(e.newValue||'{}');cart={};if(incoming&&typeof incoming==='object'&&!Array.isArray(incoming))for(const[id,n]of Object.entries(incoming))if(byId.has(id)&&validWeight(n))cart[id]=n;render();}catch{}}});
})();
